from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    zeros = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 2]
    if not zeros or not twos:
        return g

    zr = [r for r, c in zeros]
    zc = [c for r, c in zeros]
    height = max(zr) - min(zr) + 1
    width = max(zc) - min(zc) + 1
    sr, sc = min(zr), min(zc)

    tr = min(r for r, c in twos)
    tc = min(c for r, c in twos)

    def legal(r, c):
        if r < 0 or c < 0 or r + height > h or c + width > w:
            return False
        return all(g[y][x] != 3
                   for y in range(r, r + height)
                   for x in range(c, c + width))

    start = (sr, sc)
    seen = {start}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p not in seen and legal(*p):
                seen.add(p)
                q.append(p)

    dest = min(seen, key=lambda p: (abs(p[0] - tr) + abs(p[1] - tc),
                                    abs(p[0] - sr) + abs(p[1] - sc)))

    for r, c in zeros:
        g[r][c] = 1
    for r in range(dest[0], dest[0] + height):
        for c in range(dest[1], dest[1] + width):
            g[r][c] = 0
    return g
