from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 0]
    if not zeros:
        return g

    r0 = min(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    bh = max(r for r, c in zeros) - r0 + 1
    bw = max(c for r, c in zeros) - c0 + 1

    def valid(r, c):
        return (0 <= r <= h - bh and 0 <= c <= w - bw and
                all(g[y][x] != 3
                    for y in range(r, r + bh)
                    for x in range(c, c + bw)))

    start = (r0, c0)
    dist = {start: 0}
    q = deque([start])
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p not in dist and valid(*p):
                dist[p] = dist[(r, c)] + 1
                q.append(p)

    # If the colored target can be reached, stop on it; otherwise follow
    # the corridor to its furthest reachable position.
    target_positions = [
        p for p in dist
        if any(g[y][x] == 2
               for y in range(p[0], p[0] + bh)
               for x in range(p[1], p[1] + bw))
    ]
    if target_positions:
        dest = max(target_positions, key=lambda p: dist[p])
    else:
        dest = max(dist, key=lambda p: (dist[p], p[0], p[1]))

    for r, c in zeros:
        g[r][c] = 1
    for r in range(dest[0], dest[0] + bh):
        for c in range(dest[1], dest[1] + bw):
            g[r][c] = 0
    return g
